    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] tokens = br.readLine().trim().split("\\s+");
        int m = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        int[] toDelete = new int[m];
        for (int i = 0; i < m; i++) toDelete[i] = Integer.parseInt(st.nextToken());
        TreeNode root = null;
        if (tokens.length > 0 && !tokens[0].equals("null") && !tokens[0].isEmpty()) {
            root = new TreeNode(Integer.parseInt(tokens[0]));
            ArrayDeque<TreeNode> q = new ArrayDeque<>();
            q.add(root);
            int i = 1;
            while (!q.isEmpty() && i < tokens.length) {
                TreeNode node = q.poll();
                if (i < tokens.length && !tokens[i].equals("null")) {
                    node.left = new TreeNode(Integer.parseInt(tokens[i]));
                    q.add(node.left);
                }
                i++;
                if (i < tokens.length && !tokens[i].equals("null")) {
                    node.right = new TreeNode(Integer.parseInt(tokens[i]));
                    q.add(node.right);
                }
                i++;
            }
        }
        List<TreeNode> forest = delNodes(root, toDelete);
        List<Integer> ans = new ArrayList<>();
        for (TreeNode node : forest) ans.add(node.val);
        Collections.sort(ans);
        StringBuilder sb = new StringBuilder();
        sb.append(ans.size()).append("\n");
        for (int i = 0; i < ans.size(); i++) sb.append(ans.get(i)).append(i + 1 < ans.size() ? " " : "\n");
        System.out.print(sb);
    }
}

