def gen(rng):
    def make(n, shape):
        vals = rng.sample(range(1, 10**9 + 1), n) if n > 1000 else rng.sample(range(1, 1001), n)
        left = [-1] * n
        right = [-1] * n
        if shape == 'random':
            free = [(0, 0), (0, 1)]
            for i in range(1, n):
                j = rng.randrange(len(free))
                free[j], free[-1] = free[-1], free[j]
                p, side = free.pop()
                if side == 0:
                    left[p] = i
                else:
                    right[p] = i
                free.append((i, 0))
                free.append((i, 1))
        elif shape == 'left':
            for i in range(1, n):
                left[i - 1] = i
        elif shape == 'zigzag':
            for i in range(1, n):
                if i % 2:
                    left[i - 1] = i
                else:
                    right[i - 1] = i
        elif shape == 'deep':
            L = min(n, 4900)
            depth = [0] * n
            for i in range(1, L):
                if rng.random() < 0.5:
                    left[i - 1] = i
                else:
                    right[i - 1] = i
                depth[i] = i
            free = []
            for i in range(L):
                if left[i] == -1:
                    free.append((i, 0))
                if right[i] == -1:
                    free.append((i, 1))
            for i in range(L, n):
                while True:
                    j = rng.randrange(len(free))
                    if depth[free[j][0]] + 1 <= 4990:
                        break
                free[j], free[-1] = free[-1], free[j]
                p, side = free.pop()
                if side == 0:
                    left[p] = i
                else:
                    right[p] = i
                depth[i] = depth[p] + 1
                free.append((i, 0))
                free.append((i, 1))
        else:  # complete
            for i in range(1, n):
                p = (i - 1) // 2
                if i % 2:
                    left[p] = i
                else:
                    right[p] = i
        out = [str(vals[0])]
        q = [0]
        qi = 0
        while qi < len(q):
            u = q[qi]
            qi += 1
            for c in (left[u], right[u]):
                if c == -1:
                    out.append('null')
                else:
                    out.append(str(vals[c]))
                    q.append(c)
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out), vals

    def case(n, shape, p=None):
        s, vals = make(n, shape)
        if p is None:
            p = rng.choice([0.1, 0.3, 0.5, 0.9])
        d = [v for v in vals if rng.random() < p]
        if not d:
            d = [rng.choice(vals)]
        rng.shuffle(d)
        return s + '\n' + str(len(d)) + '\n' + ' '.join(map(str, d))

    tests = ['5\n1\n5', '5 3 8\n1\n5', '8 4\n2\n8 4', '1 2 3 4 5 6 7\n2\n3 5',
             '10 20 30 null 40 50\n1\n10', '1 null 2 null 3\n1\n2', '1 2 3\n3\n1 2 3']
    for _ in range(40):
        n = rng.randint(1, 14)
        tests.append(case(n, rng.choice(['random', 'random', 'left', 'zigzag', 'complete'])))
    N = 100000
    tests.append(case(N, 'random', 0.3))
    tests.append(case(N, 'complete', 0.05))
    tests.append(case(N, 'deep', 0.01))
    tests.append(case(5000, 'left', 0.002))
    tests.append(case(5000, 'zigzag', 0.01))
    return tests
